    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if seen[i][j] or g[i][j]==bg: continue
            q=[(i,j)]; seen[i][j]=True; comp=[]
            while q:
                c=q.pop(); comp.append(c)
                for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=c[0]+di,c[1]+dj
                    if 0<=x<h and 0<=y<w and not seen[x][y] and g[x][y]==g[c[0]][c[1]]:
                        seen[x][y]=True; q.append((x,y))
            out.append(comp)
    return out
def d(b,m): return min(abs(r-m[0])+abs(c-m[1]) for r,c in b)
def solve_nearest(g):
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    cs=comps_of(g,bg); blks=[c for c in cs if len(c)>1]; marks=[c[0] for c in cs if len(c)==1]
    colcnt=Counter(x for row in g for x in row)
    out=[row[:] for row in g]
    for b in blks:
        ds=sorted((d(b,m),g[m[0]][m[1]]) for m in marks)
        dd=ds[0][0]; cand=sorted(set(col for dist,col in ds if dist==dd))
        win=min(cand,key=lambda c:(colcnt[c],c))
        for r,c in b: out[r][c]=win
    return out
ok_all=all(solve_nearest(G[f'Demo pair {i} input'])==G[f'Demo pair {i} output'] for i in (1,2))
print('both demos OK' if ok_all else 'MISMATCH')
ti=G['Test input']
if not ok_all: print(json.dumps(solve_nearest(ti)))
else: print(json.dumps(solve_nearest(ti)))

